def transform(grid):
    """Replace marker 2 cells using the grid's main-diagonal symmetry."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 2:
                out[r][c] = grid[c][r]
    return out
